import java.util.ArrayList;import java.util.LinkedHashMap;import java.util.Map;import java.util.LinkedList;import java.util.Queue;
public class Graph {
 private final Map<Integer,ArrayList<Integer>> adjacencyList=new LinkedHashMap<>();
 public String addVertex(int v){if(adjacencyList.containsKey(v))return "Vertex already exists.";adjacencyList.put(v,new ArrayList<>());return "Vertex added successfully.";}
 public String addEdge(int from,int to){if(!adjacencyList.containsKey(from)||!adjacencyList.containsKey(to))return "Both vertices must exist before adding an edge.";if(adjacencyList.get(from).contains(to))return "Edge already exists.";adjacencyList.get(from).add(to);adjacencyList.get(to).add(from);return "Edge added successfully between "+from+" and "+to+".";}
 public void display(){if(adjacencyList.isEmpty()){System.out.println("Graph is empty.");return;}System.out.println("\nGraph (Adjacency List)");System.out.println("---------------------");for(Map.Entry<Integer,ArrayList<Integer>> e:adjacencyList.entrySet()){System.out.print(e.getKey()+" -> ");if(e.getValue().isEmpty()){System.out.println("No connections");continue;}for(int i=0;i<e.getValue().size();i++)System.out.print(e.getValue().get(i)+(i<e.getValue().size()-1?", ":""));System.out.println();}}
 public TraversalResult bfs(int start){if(!adjacencyList.containsKey(start))return TraversalResult.failure("Starting vertex does not exist.");long t=System.nanoTime(),steps=0;boolean[] visited=new boolean[maxVertexValue()+1];Queue<Integer> q=new LinkedList<>();StringBuilder order=new StringBuilder();q.offer(start);visited[start]=true;while(!q.isEmpty()){int cur=q.poll();steps++;if(order.length()>0)order.append(" -> ");order.append(cur);for(int n:adjacencyList.get(cur)){steps++;if(!visited[n]){visited[n]=true;q.offer(n);}}}return TraversalResult.success(order.toString(),steps,System.nanoTime()-t);}
 public TraversalResult dfs(int start){if(!adjacencyList.containsKey(start))return TraversalResult.failure("Starting vertex does not exist.");long t=System.nanoTime();boolean[] visited=new boolean[maxVertexValue()+1];StringBuilder order=new StringBuilder();long[] steps={0};dfsRecursive(start,visited,order,steps);return TraversalResult.success(order.toString(),steps[0],System.nanoTime()-t);}
 private void dfsRecursive(int v,boolean[] visited,StringBuilder order,long[] steps){visited[v]=true;steps[0]++;if(order.length()>0)order.append(" -> ");order.append(v);for(int n:adjacencyList.get(v)){steps[0]++;if(!visited[n])dfsRecursive(n,visited,order,steps);}}
 private int maxVertexValue(){int max=0;for(int v:adjacencyList.keySet())if(v>max)max=v;return max;} public int vertexCount(){return adjacencyList.size();}
}
